mapper.select:
SELECT id,role_code,role_name
FROM admin_role
ORDER BY role_code
LIMIT #{limit}
OFFSET #{offset}

SELECT id
FROM admin_role
WHERE role_code=#{code}

mapper.update:
UPDATE admin_role
SET role_name=#{name}
WHERE role_code=#{code}

mapper.insert:
INSERT INTO admin_role_menu(role_id,menu_id) SELECT #{id},id
FROM admin_menu
WHERE menu_code=#{code}

INSERT INTO admin_role_permission(role_id,permission_id) SELECT #{id},id
FROM admin_permission
WHERE permission_code=#{code}
